// End-to-end check with the real MiddleEarth payload (generated by `npm run payload`) against a MOCK game folder
// in a temp directory. Skipped when the payload hasn't been generated. Never touches the real game.
import fs from 'node:fs/promises'
import path from 'node:path'
import { describe, expect, it } from 'vitest'
import { ModEngine } from '../src/main/core/modManager/engine'
import { loadRegistry } from '../src/main/core/modManager/manifest'
import { makeGame, snapshot, tmp } from './helpers'

const modsRoot = path.resolve(__dirname, '..', 'mods')
const original = path.join(modsRoot, 'middleearth', 'originals', 'Assets', 'DLC', 'Shared', 'Upgrade1.Civ5Pkg')
const ready = await fs.access(original).then(() => true, () => false)

describe.skipIf(!ready)('real MiddleEarth payload (mock game folder)', () => {
  it('installs and fully restores vanilla', async () => {
    const { mods, errors } = await loadRegistry(modsRoot)
    expect(errors).toEqual([])
    const game = await makeGame(await tmp('civ5mm-real-'))
    await fs.copyFile(original, path.join(game, 'Assets', 'DLC', 'Shared', 'Upgrade1.Civ5Pkg'))
    const vanilla = await snapshot(game)
    const engine = new ModEngine(await tmp())
    await engine.switchTo(game, 'middleearth', mods)
    expect(await engine.inspect(game, mods)).toMatchObject({ kind: 'mod', modId: 'middleearth' })
    expect((await engine.state.read()).install?.files.length).toBe(mods[0].manifest.files.length)
    await engine.switchTo(game, 'vanilla', mods)
    expect(await snapshot(game)).toEqual(vanilla)
    await fs.rm(game, { recursive: true })
  }, 120000)
})
